import React from 'react';
import { View, Text, StatusBar, SafeAreaView } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';

const Container = styled.View`
  flex: 1;
  background-color: ${colors.background};
`;

const MapPlaceholder = styled.View`
  flex: 1;
  background-color: #e0e0e0;
  justify-content: center;
  align-items: center;
`;

const TopBar = styled.View`
  position: absolute;
  top: ${spacing.xl}px;
  left: ${spacing.md}px;
  right: ${spacing.md}px;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  z-index: 10;
`;

const IconButton = styled.TouchableOpacity`
  width: 45px;
  height: 45px;
  border-radius: ${borderRadius.full}px;
  background-color: ${colors.white};
  justify-content: center;
  align-items: center;
  elevation: 5;
  shadow-color: #000;
  shadow-offset: 0px 2px;
  shadow-opacity: 0.25;
  shadow-radius: 3.84px;
`;

const BottomSheet = styled.View`
  background-color: ${colors.white};
  border-top-left-radius: 30px;
  border-top-right-radius: 30px;
  padding: ${spacing.lg}px;
  padding-bottom: ${spacing.xl + spacing.md}px;
  elevation: 20;
  shadow-color: #000;
  shadow-offset: 0px -5px;
  shadow-opacity: 0.1;
  shadow-radius: 10px;
`;

const Greeting = styled.Text`
  font-size: 22px;
  font-weight: bold;
  color: ${colors.text};
  margin-bottom: ${spacing.xs}px;
  text-align: center;
`;

const Subtitle = styled.Text`
  font-size: 14px;
  color: ${colors.textSecondary};
  margin-bottom: ${spacing.lg}px;
  text-align: center;
`;

const SearchButton = styled.TouchableOpacity`
  background-color: ${colors.secondary};
  border-radius: ${borderRadius.xl}px;
  height: 60px;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  padding-horizontal: ${spacing.lg}px;
`;

const SearchButtonText = styled.Text`
  color: ${colors.white};
  font-size: 18px;
  font-weight: 600;
  margin-right: ${spacing.sm}px;
`;

const HomeScreen = () => {
  return (
    <Container>
      <StatusBar barStyle="dark-content" backgroundColor="transparent" translucent />

      <TopBar>
        <IconButton>
          <Icon name="menu" size={28} color={colors.secondary} />
        </IconButton>
        <IconButton>
          <Icon name="chat" size={24} color={colors.secondary} />
        </IconButton>
      </TopBar>

      <MapPlaceholder>
        <Icon name="map" size={100} color="#bdbdbd" />
        <Text style={{ color: '#9e9e9e', marginTop: 10 }}>Mapa Interativo</Text>
      </MapPlaceholder>

      <BottomSheet>
        <Greeting>Bom dia, Passageiro!</Greeting>
        <Subtitle>Para onde vamos hoje?</Subtitle>

        <SearchButton activeOpacity={0.8}>
          <SearchButtonText>Escolher Destino</SearchButtonText>
          <Icon name="near-me" size={20} color={colors.white} />
        </SearchButton>
      </BottomSheet>
    </Container>
  );
};

export default HomeScreen;
